package com.ecommerce.review; import com.ecommerce.product.*; import com.ecommerce.user.*; import com.ecommerce.common.ApiException; import jakarta.validation.constraints.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/products/{productId}/reviews") public class ReviewController {record Req(@Min(1)@Max(5) short rating,String comment){} private final ReviewRepository reviews;private final ProductRepository products;private final UserRepository users;public ReviewController(ReviewRepository r,ProductRepository p,UserRepository u){reviews=r;products=p;users=u;} @GetMapping List<Review> list(@PathVariable UUID productId){return reviews.findByProductId(productId);} @PostMapping Review add(@PathVariable UUID productId,@RequestBody @jakarta.validation.Valid Req x,Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(reviews.existsByProductIdAndUserId(productId,u.getId()))throw new ApiException("You already reviewed this product");Review r=new Review();r.setProduct(products.findById(productId).orElseThrow(()->new ApiException("Product not found")));r.setUser(u);r.setRating(x.rating());r.setComment(x.comment());return reviews.save(r);}}
